/**
 * SoundManager — powered by Howler.js
 *
 * Sound files live in: static/assets/sounds/
 * All files are .ogg (generated by Tunic8-Bit engine).
 *
 * Triggered actions:
 *   shoot          Player fires a bullet
 *   enemyDie       Enemy is destroyed
 *   playerHit      Player takes damage
 *   collectGem     Diamond / crystal collected
 *   collectHeart   Heart collected
 *   powerUp        Bullet power-up collected
 *   powerDown      Power level reduced (alien reached bottom)
 *   levelUp        Level cleared
 *   gameOver       Game over
 *   bossAppear     Boss spawns
 *   bulletBounce   Level-4 bullet bounces off wall
 *   alienShoot     Alien King fires a projectile
 *   bgMusic        Background music (loops)
 */

const SoundManager = {
    sounds: {},
    sfxEnabled: true,
    musicEnabled: true,
    initialized: false,

    init() {
        if (this.initialized) return;
        this.initialized = true;

        // Guard: Howler must be loaded via CDN before this runs
        if (typeof Howl === 'undefined') {
            console.warn('[SoundManager] Howler.js not loaded — audio disabled.');
            return;
        }

        // Only list formats we actually have — avoids 404s that block loading
        const defs = {
            shoot:        { src: ['assets/sounds/shoot.ogg'],        volume: 0.35 },
            enemyDie:     { src: ['assets/sounds/enemy_die.ogg'],    volume: 0.5  },
            playerHit:    { src: ['assets/sounds/player_hit.ogg'],   volume: 0.6  },
            collectGem:   { src: ['assets/sounds/collect_gem.ogg'],  volume: 0.4  },
            collectHeart: { src: ['assets/sounds/collect_heart.ogg'],volume: 0.55 },
            powerUp:      { src: ['assets/sounds/power_up.ogg'],     volume: 0.65 },
            powerDown:    { src: ['assets/sounds/power_down.ogg'],   volume: 0.5  },
            levelUp:      { src: ['assets/sounds/level_up.ogg'],     volume: 0.7  },
            gameOver:     { src: ['assets/sounds/game_over.ogg'],    volume: 0.7  },
            bossAppear:   { src: ['assets/sounds/boss_appear.ogg'],  volume: 0.8  },
            bulletBounce: { src: ['assets/sounds/bullet_bounce.ogg'],volume: 0.25 },
            alienShoot:   { src: ['assets/sounds/alien_shoot.ogg'],  volume: 0.4  },
            bgMusic:      { src: ['assets/sounds/bg_music.ogg'],     volume: 0.28, loop: true },
        };

        for (const [key, def] of Object.entries(defs)) {
            this.sounds[key] = new Howl({
                src:    def.src,
                volume: def.volume ?? 0.5,
                loop:   def.loop ?? false,
                onloaderror: (_id, err) => {
                    console.warn(`[SoundManager] '${key}' failed to load:`, err);
                }
            });
        }

        console.log('[SoundManager] Initialised —', Object.keys(this.sounds).length, 'sounds loaded.');
    },

    /** Play a one-shot SFX by name */
    play(name) {
        if (!this.sfxEnabled) return;
        if (name === 'bgMusic') { this.startMusic(); return; }
        const sound = this.sounds[name];
        if (sound) {
            sound.play();
        } else {
            console.warn(`[SoundManager] Unknown sound: '${name}'`);
        }
    },

    startMusic() {
        if (!this.musicEnabled) return;
        const music = this.sounds.bgMusic;
        if (music && !music.playing()) music.play();
    },

    stopMusic() {
        this.sounds.bgMusic?.stop();
    },

    toggleSfx() {
        this.sfxEnabled = !this.sfxEnabled;
        return this.sfxEnabled;
    },

    toggleMusic() {
        this.musicEnabled = !this.musicEnabled;
        if (!this.musicEnabled) this.stopMusic();
        else this.startMusic();
        return this.musicEnabled;
    }
};

export default SoundManager;
